<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {ChevronLeft,Minus,Plus,ShoppingBag,Truck,ShieldCheck,RotateCcw} from 'lucide-vue-next';import {api,idr} from '../api';import type {Product} from '../stores';import {useCart,useSession,useUi} from '../stores';const route=useRoute(),router=useRouter(),product=ref<Product|null>(null),qty=ref(1),loading=ref(true),error=ref(''),cart=useCart(),session=useSession(),ui=useUi();onMounted(async()=>{try{product.value=await api(`/products/${route.params.slug}`)}catch(e:any){error.value=e.message}finally{loading.value=false}});async function add(){if(!session.user)return router.push('/login');try{await cart.add(product.value!.id,qty.value);ui.toast('Added to your shopping bag');ui.cartOpen=true}catch(e:any){ui.toast(e.message,'error')}}</script>
<template><main class="container product-page"><RouterLink to="/products" class="back-link"><ChevronLeft :size="14"/> Back to collection</RouterLink><div v-if="loading" class="detail-grid"><div class="skeleton detail-skeleton"></div><div class="skeleton detail-copy-skeleton"></div></div><p v-else-if="error" class="alert error">{{error}}</p><section v-else-if="product" class="detail-grid"><div class="detail-gallery"><img :src="product.images[0]?.imageUrl" :alt="product.name"/></div><div class="detail-copy"><small>{{product.category.name}} · SKU {{product.sku}}</small><h1>{{product.name}}</h1><strong>{{idr(product.price)}}</strong><div class="rule"></div><p>{{product.description}}</p><span class="inventory" :class="{low:product.stock<=5}">{{product.stock?`${product.stock} units available`:'Currently out of stock'}}</span><div class="purchase-row"><div class="qty"><button @click="qty=Math.max(1,qty-1)"><Minus :size="14"/></button><span>{{qty}}</span><button @click="qty=Math.min(product.stock,qty+1)"><Plus :size="14"/></button></div><button class="btn-primary add-detail" :disabled="!product.stock" @click="add"><ShoppingBag :size="16"/> Add to Bag</button></div><div class="detail-benefits"><p><Truck :size="17"/><span><b>Express delivery</b><small>Ships within 24 hours</small></span></p><p><ShieldCheck :size="17"/><span><b>Authenticity guaranteed</b><small>Quality inspected</small></span></p><p><RotateCcw :size="17"/><span><b>30-day returns</b><small>Easy and effortless</small></span></p></div></div></section></main></template>
